package cli

import (
	"bytes"
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/spf13/cobra"
)

// Mimics enable on a fresh repo: root's prerun declines (not set up), the leaf
// builds its own logger and SetContexts it, then logs. Does root's PostRun flush?
func TestScratch_LeafBuiltLoggerIsFlushed(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "f.txt", "init")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "init")
	t.Chdir(dir)
	// deliberately NOT markRepoSetUpForLogging: root's prerun must decline

	root := NewRootCmd()
	probe := &cobra.Command{
		Use:    "__scratch_leaf_logger",
		Hidden: true,
		Args:   cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			if logging.LoggerFromContext(ctx) != nil {
				t.Fatal("root prerun should have declined for a not-set-up repo")
			}
			l, err := newLogger(ctx)
			if err != nil {
				t.Fatalf("newLogger: %v", err)
			}
			ctx = logging.WithLogger(ctx, l)
			cmd.SetContext(ctx)
			logging.Warn(ctx, "leaf built this logger")
			return nil
		},
	}
	root.AddCommand(probe)
	root.SetOut(&bytes.Buffer{})
	root.SetErr(&bytes.Buffer{})
	root.SetArgs([]string{probe.Use})
	if err := root.Execute(); err != nil {
		t.Fatalf("execute: %v", err)
	}

	content, err := os.ReadFile(filepath.Join(dir, paths.EntireDir, "logs", "entire.log"))
	if err != nil {
		t.Fatalf("read log: %v", err)
	}
	if !bytes.Contains(content, []byte("leaf built this logger")) {
		t.Errorf("LEAF-BUILT LOGGER NOT FLUSHED. file=%q", content)
	} else {
		t.Log("flushed correctly")
	}
